// Negative Mass - stress test simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var ten=[1.2,8,60], den=[4.5,2.1,0.9];
console.log("Negative Mass - specific strength by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var spec=(ten[m]/den[m]).toFixed(2);
  console.log("Mark "+(m+1)+": "+ten[m]+" GPa / "+den[m]+" g/cm^3 = specific strength "+spec);
  var cable=Math.round(ten[m]*1e9*0.0001/9.81); // 1 cm^2 cable
  console.log("  a 1 cm^2 cable holds ~"+cable.toLocaleString()+" kg");
}

